import os
import base64
from typing import Any, Dict, Optional

from google.cloud import vision


def check_image_safety(
    image_path: Optional[str] = None,
    image_bytes: Optional[bytes] = None,
) -> Dict[str, Any]:
    if not image_path and image_bytes is None:
        raise ValueError("Provide either image_path or image_bytes.")

    if image_path and image_bytes is not None:
        raise ValueError("Provide only one of image_path or image_bytes.")

    if image_path:
        with open(image_path, "rb") as f:
            image_bytes = f.read()

    if image_bytes is None:
        raise ValueError("Image data could not be loaded.")

    client = vision.ImageAnnotatorClient()

    image = vision.Image(content=image_bytes)
    response = client.safe_search_detection(image=image)

    if response.error.message:
        raise RuntimeError(f"Google Cloud Vision API error: {response.error.message}")

    safe = response.safe_search_annotation

    likelihood_names = {
        vision.Likelihood.UNKNOWN: "UNKNOWN",
        vision.Likelihood.VERY_UNLIKELY: "VERY_UNLIKELY",
        vision.Likelihood.UNLIKELY: "UNLIKELY",
        vision.Likelihood.POSSIBLE: "POSSIBLE",
        vision.Likelihood.LIKELY: "LIKELY",
        vision.Likelihood.VERY_LIKELY: "VERY_LIKELY",
    }

    result = {
        "provider": "Google Cloud Vision",
        "credentials_env": "GOOGLE_APPLICATION_CREDENTIALS",
        "image_base64_size": len(base64.b64encode(image_bytes)),
        "safe_search": {
            "adult": likelihood_names.get(safe.adult, str(safe.adult)),
            "spoof": likelihood_names.get(safe.spoof, str(safe.spoof)),
            "medical": likelihood_names.get(safe.medical, str(safe.medical)),
            "violence": likelihood_names.get(safe.violence, str(safe.violence)),
            "racy": likelihood_names.get(safe.racy, str(safe.racy)),
        },
    }

    flagged_levels = {"POSSIBLE", "LIKELY", "VERY_LIKELY"}
    result["unsafe_or_sensitive"] = any(
        value in flagged_levels for value in result["safe_search"].values()
    )

    return result
